//! wpa.library's functions: a Wi-Fi station's WPA2-Personal side for a
//! driver whose radio leaves it to the host - the network's key from its
//! passphrase, the station's RSN element, and the 4-way and group key
//! handshakes. Open it with OpenLibrary("wpa.library", 1); the structures
//! are in sdk.wpa.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/wpa_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const wpa = @import("../libs/wpa/wpa.zig");
const utility = @import("../libs/utility/utility.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "wpa.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const PassphraseKey = libraries.lvo(4);
    pub const ParseSecurity = libraries.lvo(5);
    pub const StationElement = libraries.lvo(6);
    pub const CreateHandshake = libraries.lvo(7);
    pub const DeleteHandshake = libraries.lvo(8);
    pub const HandshakeFrame = libraries.lvo(9);
    pub const HandshakeSent = libraries.lvo(10);
    pub const HandshakeStatus = libraries.lvo(11);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const PassphraseKey = *const fn (*WPABase, [*:0]const u8, [*]const u8, u32, *[32]u8) callconv(.c) bool;
    pub const ParseSecurity = *const fn (*WPABase, [*]const u8, *wpa.Security) callconv(.c) bool;
    pub const StationElement = *const fn (*WPABase, [*]const u8, [*]u8, u32) callconv(.c) u32;
    pub const CreateHandshake = *const fn (*WPABase, ?[*]const utility.TagItem) callconv(.c) ?*wpa.Handshake;
    pub const DeleteHandshake = *const fn (*WPABase, ?*wpa.Handshake) callconv(.c) void;
    pub const HandshakeFrame = *const fn (*WPABase, *wpa.Handshake, [*]const u8, u32) callconv(.c) void;
    pub const HandshakeSent = *const fn (*WPABase, *wpa.Handshake, u32) callconv(.c) void;
    pub const HandshakeStatus = *const fn (*WPABase, *wpa.Handshake) callconv(.c) u32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const WPABase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *WPABase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The network's key from `passphrase` (8 to 63 characters, or 64 hex
    /// digits) and its name (`ssid`, `ssid_length` bytes), into `key`: false
    /// for a passphrase or name out of bounds, or without crypto.library.
    pub fn PassphraseKey(self: *WPABase, passphrase: [*:0]const u8, ssid: [*]const u8, ssid_length: u32, key: *[32]u8) bool {
        return libraries.call(self, LVO.PassphraseKey, Fn.PassphraseKey, .{ passphrase, ssid, ssid_length, key });
    }

    /// What the RSN or WPA element at `element` (from its id on) offers, into
    /// `security`: false for one that makes no sense.
    pub fn ParseSecurity(self: *WPABase, element: [*]const u8, security: *wpa.Security) bool {
        return libraries.call(self, LVO.ParseSecurity, Fn.ParseSecurity, .{ element, security });
    }

    /// The RSN element a station joins the access point's (`element`) with,
    /// into `into` (`size` bytes): its length, 0 when the network asks for
    /// what the library does not do.
    pub fn StationElement(self: *WPABase, element: [*]const u8, into: [*]u8, size: u32) u32 {
        return libraries.call(self, LVO.StationElement, Fn.StationElement, .{ element, into, size });
    }

    /// A key handshake, as the tags say (WPAH_*): null when one is missing
    /// or there is no memory.
    pub fn CreateHandshake(self: *WPABase, tags: ?[*]const utility.TagItem) ?*wpa.Handshake {
        return libraries.call(self, LVO.CreateHandshake, Fn.CreateHandshake, .{tags});
    }

    /// The handshake freed.
    pub fn DeleteHandshake(self: *WPABase, handshake: ?*wpa.Handshake) void {
        return libraries.call(self, LVO.DeleteHandshake, Fn.DeleteHandshake, .{handshake});
    }

    /// An EAPOL frame from the access point, from its 802.1X header on
    /// (`length` bytes).
    pub fn HandshakeFrame(self: *WPABase, handshake: *wpa.Handshake, frame: [*]const u8, length: u32) void {
        return libraries.call(self, LVO.HandshakeFrame, Fn.HandshakeFrame, .{ handshake, frame, length });
    }

    /// The frame the handshake asked to send as number `frame` has gone over
    /// the air.
    pub fn HandshakeSent(self: *WPABase, handshake: *wpa.Handshake, frame: u32) void {
        return libraries.call(self, LVO.HandshakeSent, Fn.HandshakeSent, .{ handshake, frame });
    }

    /// Where the handshake stands: WPAHS_*.
    pub fn HandshakeStatus(self: *WPABase, handshake: *wpa.Handshake) u32 {
        return libraries.call(self, LVO.HandshakeStatus, Fn.HandshakeStatus, .{handshake});
    }
};
